exercise.referenceSolution:
#include <iostream>

namespace metric {
int length(int meters) { return meters * 100; }
}
namespace imperial {
int length(int feet) { return feet * 12; }
}
int main() {
    int meters{}, feet{};
    if (!(std::cin >> meters >> feet)) return 1;
    std::cout << metric::length(meters) << ' ' << imperial::length(feet) << '\n';
}
